/* view-model: a GObject whose property really notifies */
static void vm_login_set_user(VmLogin *self, const char *v) {
    if (g_strcmp0(self->user, v) == 0) return;      /* notify only on change */
    g_free(self->user); self->user = g_strdup(v);
    g_object_notify_by_pspec(G_OBJECT(self), properties[PROP_USER]);
}
